from copy import deepcopy


def run_task_command(records, argv):
    if not isinstance(records, list) or not isinstance(argv, list) or not all(isinstance(x, str) for x in argv):
        raise ValueError("invalid input")
    for item in records:
        if not isinstance(item, dict) or set(item) != {"text", "done"} or not isinstance(item["text"], str) or not item["text"] or not isinstance(item["done"], bool):
            raise ValueError("invalid record")
    if not argv:
        raise ValueError("missing command")
    result = deepcopy(records)
    command = argv[0]
    if command == "add":
        if len(argv) != 2 or not argv[1]:
            raise ValueError("invalid add")
        result.append({"text": argv[1], "done": False})
        return result, f"Added {len(result)}"
    if command == "show":
        if len(argv) != 1:
            raise ValueError("invalid show")
        if not result:
            return result, "No tasks"
        lines = [f"{i}. [{'x' if task['done'] else ' '}] {task['text']}" for i, task in enumerate(result, 1)]
        return result, "\n".join(lines)
    if command == "finish":
        if len(argv) != 2 or not argv[1].isdigit():
            raise ValueError("invalid finish")
        number = int(argv[1])
        if number < 1 or number > len(result):
            raise ValueError("task out of range")
        result[number]["done"] = True
        return result, f"Finished {number}"
    raise ValueError("unknown command")

